# A156 is a helper of 500 sh steps called 500 times: 250,000 step copies, most of the time outside this rule
# (2.6 s at `653b153`, about 2.3 s after the slice on the building machine). The R2-z cases are 35 to 43 KB files of
# helpers inlined a thousand times: 1.4 to 2.1 s at `653b153` and 1.6 to 2.3 s after the slice. None of them is part
# of the time limit below; test_large_files_stay_near_the_base bounds them.
SLOW = {"A156", "R2-z001_budget_alias_pass", "R2-z002_budget_method_pass", "R2-z003_budget_length_fp",
        "R2-z004_budget_700_slow"}

CATALOG = load()


def verdict(text: str) -> str:
    result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
    found = [f for f in result.findings if f.rule == "OBAAF-JEN-009"]
    if found:
        order = {"high": 3, "medium": 2, "low": 1}
        return "finding-" + max(found, key=lambda f: order[f.severity]).severity
    row = next((row for row in jenkins.coverage(result, result.findings) if row["rule"] == "OBAAF-JEN-009"), None)
    if row is None or row["status"] in ("pass", "not applicable"):
        return "quiet"
    return row["status"]


RANK = {"quiet": 0, "unknown": 1, "finding-low": 2, "finding-medium": 3, "finding-high": 4}


class InjectionBypassTest(unittest.TestCase):
    def test_every_attempt(self):
        for name, expected, _before, _why, text in CASES:
            with self.subTest(case=name):
                self.assertEqual(verdict(text), expected)

    def test_limits_name_real_cases_whose_answer_differs(self):
        answers = {c[0]: c[1] for c in CASES}
        self.assertLessEqual(set(LIMITS), set(answers))
        for name, (judged, _why) in LIMITS.items():
            self.assertNotEqual(answers[name], judged, name)

    def test_every_other_case_is_the_judged_answer(self):
        # Outside LIMITS the rule gives exactly the answer the attacker (or the run) judged right.
        for name, expected, _before, why, _text in CASES:
            if name not in LIMITS:
                with self.subTest(case=name):
                    self.assertNotIn(name, LIMITS)

    def test_no_stated_limit_is_quiet_where_a_finding_was_judged_unless_it_was_before(self):
        # A stated limit may be quiet where a finding or cannot tell was judged only where the rule was quiet there
        # before the slice too: the slice adds no new way past. Those left are listed in LIMITS with their reasons.
        before = {c[0]: c[2] for c in CASES}
        answers = {c[0]: c[1] for c in CASES}
        for name, (judged, _why) in LIMITS.items():
            with self.subTest(case=name):
                if judged != "quiet" and answers[name] == "quiet":
                    self.assertEqual(before[name], "quiet")

    def test_no_attempt_is_slow(self):
        for name, _expected, _before, _why, text in CASES:
            if name in SLOW:
                continue
            started = time.monotonic()
            verdict(text)
            with self.subTest(case=name):
                self.assertLess(time.monotonic() - started, 3.0)

    def test_old_messages_kept_for_a_baseline(self):
        # A Jenkins finding's message is its identity in a baseline: where the rule reported a case before the slice,
        # with a source read directly or through one variable, it words it as before.
        texts = ['node { sh "echo ${env.CHANGE_TITLE}" }',
                 'node { sh "deploy ${params.TARGET}" }',
                 'node { def t = env.CHANGE_BRANCH\n sh "git checkout ${t}" }',
                 "node { def m = sh(script: 'git log -1 --pretty=%B', returnStdout: true).trim()\n sh \"echo ${m}\" }",
                 "pipeline { agent any\n parameters { string(name: 'TARGET') }\n stages { stage('a') { steps { "
                 "sh \"deploy ${TARGET}\" } } } }"]
        messages = []
        for text in texts:
            result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
            messages += [f.message for f in result.findings if f.rule == "OBAAF-JEN-009"]
        self.assertEqual(messages, [
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of CHANGE_TITLE. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of params.TARGET. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of t (from CHANGE_BRANCH). "
            "The value becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'pipeline' builds its script with Groovy interpolation of m (from git commit text). "
            "The value becomes part of the command before the shell runs, so it can run commands of its own.",
            "The sh step in stage 'a' builds its script with Groovy interpolation of parameter TARGET. The value "
            "becomes part of the command before the shell runs, so it can run commands of its own."])


class SharedModelTest(unittest.TestCase):
    """What the slice changed in code every Jenkins rule shares (its first review's findings B1 and B11)."""

    SECRET_ENV_INDEX = (
        "pipeline {\n  agent any\n  stages {\n    stage('Deploy') {\n      when { branch 'main' }\n      steps {\n"
        "        withCredentials([string(credentialsId: 'api-token', variable: 'TOKEN')]) {\n          script {\n"
        "            env['T'] = TOKEN\n            sh \"curl -H Authorization:${env.T} https://example.com\"\n"
        "          }\n        }\n      }\n    }\n  }\n}\n")

    def test_jen_013_message_for_env_index_is_unchanged(self):
        result = jenkins.analyze("Jenkinsfile", self.SECRET_ENV_INDEX.encode(), CATALOG, None)
        messages = [f.message for f in result.findings if f.rule == "OBAAF-JEN-013"]
        self.assertEqual(len(messages), 1)
        self.assertIn("puts secret variable(s) env into its script", messages[0])

    def test_jen_013_follows_a_secret_through_this_and_set_property(self):
        # New with the slice: a secret copied with `this.T = TOKEN` or `env.setProperty('T', TOKEN)` is still a secret.
        for copy in ("this.T = TOKEN", "env.setProperty('T', TOKEN)"):
            text = self.SECRET_ENV_INDEX.replace("env['T'] = TOKEN", copy).replace("${env.T}", "${T}")
            result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
            with self.subTest(copy=copy):
                self.assertIn("OBAAF-JEN-013", {f.rule for f in result.findings})

    def test_a_slashy_string_inside_an_interpolation_is_not_a_comment(self):
        text = ("node {\n  def host = env.GIT_URL\n"
                "  sh \"git remote set-url origin ${host.replaceFirst(/^https:\\/\\//, 'https://x@')}\"\n"
                "  withCredentials([string(credentialsId: 'tok', variable: 'T')]) {\n"
                "    sh 'curl -H \"Authorization: $T\" https://api.example'\n  }\n}\n")
        result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
        self.assertIsNone(result.error)
        self.assertIn("OBAAF-JEN-001", {f.rule for f in result.findings})


class MemoAndBudgetTest(unittest.TestCase):
    """The second review of slice 2d.2: a method's result kept from another context, and the reader's budget."""

    TEXTS = {c[0]: c[4] for c in CASES}

    def stages(self, name):
        result = jenkins.analyze("Jenkinsfile", self.TEXTS[name].encode(), CATALOG, None)
        return sorted(f.job for f in result.findings if f.rule == "OBAAF-JEN-009")

    def test_a_result_cut_in_one_place_is_not_reused_in_another(self):
        self.assertEqual(self.stages("R2-k102_memo_recursion_cut"), ["one", "two"])
        for name in ("R2-k104_memo_cut_poison", "R2-k106_memo_cut_poison_quote", "R2-k107_memo_cut_poison_alias"):
            with self.subTest(case=name):
                self.assertIn("b", self.stages(name))

    def test_a_method_result_names_its_own_argument(self):
        result = jenkins.analyze("Jenkinsfile", self.TEXTS["R2-k101_memo_wrong_name"].encode(), CATALOG, None)
        messages = [f.message for f in result.findings if f.rule == "OBAAF-JEN-009"]
        self.assertEqual([m.split("interpolation of ")[1].split(".")[0] for m in messages],
                         ["t (from CHANGE_TITLE)", "u (from CHANGE_TITLE)"])

    def test_large_files_stay_near_the_base(self):
        # 1.4 to 2.1 s at `653b153` on the building machine; a generous bound for slower machines.
        for name in sorted(SLOW - {"A156"}):
            started = time.monotonic()
            jenkins.analyze("Jenkinsfile", self.TEXTS[name].encode(), CATALOG, None)
            with self.subTest(case=name):
                self.assertLess(time.monotonic() - started, 10.0)


if __name__ == "__main__":
    unittest.main()
